  insert into public.pos_sessions(pos_session_id,shop_id,shop_device_id,staff_id,pos_device_credential_id,session_token_hash,staff_credential_version,issued_at,expires_at)
   values(session,'10000000-0000-4000-8000-000000403019',device,'30000000-0000-4000-8000-000000403019',credential,'sha256:'||repeat((n+2)::text,64),7,clock_timestamp()-interval '1 minute',clock_timestamp()+interval '30 minutes');
 end loop;
end;$$;

select set_config('request.jwt.claim.role','service_role',true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
create function pg_temp.baseline_request(n integer,op text,p jsonb) returns jsonb language sql as $$
 select public.payment_history_device_v2('10000000-0000-4000-8000-000000403019',
  (value#>>array['baselines',(n-1)::text,'manifest','deviceId'])::uuid,'30000000-0000-4000-8000-000000403019',('60000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,
  'sha256:'||repeat(n::text,64),'sha256:'||repeat((n+2)::text,64),7,'baseline_'||op,p)->'result' from corpus;
$$;
insert into public.pos_sessions(pos_session_id,shop_id,shop_device_id,staff_id,pos_device_credential_id,session_token_hash,staff_credential_version,issued_at,expires_at)
 select '60000000-0000-4000-8000-000000000101','10000000-0000-4000-8000-000000403019',(value#>>'{baselines,0,manifest,deviceId}')::uuid,
  '30000000-0000-4000-8000-000000403019','50000000-0000-4000-8000-000000000001','sha256:'||repeat('c',64),7,clock_timestamp()-interval '1 minute',clock_timestamp()+interval '30 minutes' from corpus;
insert into public.pos_sessions(pos_session_id,shop_id,shop_device_id,staff_id,pos_device_credential_id,session_token_hash,staff_credential_version,issued_at,expires_at)
 select '60000000-0000-4000-8000-000000000102','10000000-0000-4000-8000-000000403019',(value#>>'{baselines,0,manifest,deviceId}')::uuid,
  '30000000-0000-4000-8000-000000403019','50000000-0000-4000-8000-000000000001','sha256:'||repeat('d',64),7,clock_timestamp()-interval '1 minute',clock_timestamp()+interval '30 minutes' from corpus;
create function pg_temp.recovery(n integer,p jsonb) returns jsonb language sql as $$
 select public.payment_history_device_v2('10000000-0000-4000-8000-000000403019',
 (value#>>array['baselines',case when n=4 then '1' else '0' end,'manifest','deviceId'])::uuid,
 '30000000-0000-4000-8000-000000403019',
 (case n when 1 then '60000000-0000-4000-8000-000000000001' when 2 then '60000000-0000-4000-8000-000000000101' when 3 then '60000000-0000-4000-8000-000000000102' else '60000000-0000-4000-8000-000000000002' end)::uuid,
 'sha256:'||repeat(case when n=4 then '2' else '1' end,64),
 'sha256:'||repeat(case n when 1 then '3' when 2 then 'c' when 3 then 'd' else '4' end,64),7,'baseline_recover',p)->'result' from corpus;
$$;
create function pg_temp.current_request(n integer,op text,p jsonb) returns jsonb language sql as $$
 select public.payment_history_device_v2('10000000-0000-4000-8000-000000403019',
 (value#>>array['baselines',case when n=4 then '1' else '0' end,'manifest','deviceId'])::uuid,
 '30000000-0000-4000-8000-000000403019',
 (case n when 1 then '60000000-0000-4000-8000-000000000001' when 2 then '60000000-0000-4000-8000-000000000101' when 3 then '60000000-0000-4000-8000-000000000102' else '60000000-0000-4000-8000-000000000002' end)::uuid,
 'sha256:'||repeat(case when n=4 then '2' else '1' end,64),
 'sha256:'||repeat(case n when 1 then '3' when 2 then 'c' when 3 then 'd' else '4' end,64),7,'baseline_'||op,p)->'result' from corpus;
$$;

create function pg_temp.retry_payload(n integer default 1) returns jsonb language sql as $$
 select jsonb_build_object('recovery_request_key',('a0000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,
  'run_id',(select value->>'run_id' from state where key='start'),
  'apply_request_key','b0000000-0000-4000-8000-000000403019','retry_failed',true);
$$;
create function pg_temp.successor_payload() returns jsonb language sql as $$
 select pg_temp.retry_payload(3)||jsonb_build_object('previous_recovery_request_key',pg_temp.retry_payload(2)->>'recovery_request_key');
$$;
create function pg_temp.run_snapshot() returns jsonb language sql as $$
 select to_jsonb(j) from public.payment_history_migration_runs j where j.run_id=(select (value->>'run_id')::uuid from state where key='start');
$$;
create function pg_temp.stage_finish(l jsonb) returns void language plpgsql as $$
declare f jsonb;begin
 select value->'baselines'->0 into f from corpus;
 perform public.payment_history_migration_worker_v1('stage_objects',l||jsonb_build_object('rows',f->'objects'));
 perform public.payment_history_migration_worker_v1('stage_movements',l||jsonb_build_object('rows',f->'movements'));
 perform public.payment_history_migration_worker_v1('finish',l||jsonb_build_object('raw_manifest',f->>'rawManifest','analysis_digest',f->>'analysisDigest'));
end;$$;
create function pg_temp.prepare_failed() returns jsonb language plpgsql as $$
declare f jsonb;s jsonb;l jsonb;u jsonb;begin
 select value->'baselines'->0 into f from corpus;
 u:=pg_temp.baseline_request(1,'upload_create',jsonb_build_object('request_key',gen_random_uuid(),'file_name','synthetic.w7history.zip','sha256',f->>'archiveSha256','byte_length',f->>'byteLength'));
 -- Synthetic storage verification fixture only; source bytes are the existing
 -- CLR/Node corpus. All subsequent job/recovery/apply calls use real SQL APIs.
 update public.payment_history_uploads set state='verified',verified_at=clock_timestamp() where upload_id=(u->>'upload_id')::uuid;
 s:=pg_temp.baseline_request(1,'start',jsonb_build_object('request_key',gen_random_uuid(),'upload_id',u->>'upload_id',
  'local_dataset_id',f#>>'{manifest,localDatasetId}','data_revision',f#>>'{manifest,dataRevision}',
  'restore_epoch',f#>>'{manifest,restoreEpoch}','restore_lineage_id',f#>>'{manifest,restoreLineageId}','writer_epoch','1'));
 l:=public.payment_history_migration_worker_v1('claim','{}')->'run';
 if l->>'run_id' is distinct from s->>'run_id' then raise exception 'fixture_worker_claim_mismatch';end if;
 insert into state values('original-lease',l);
 perform public.payment_history_migration_worker_v1('stage_objects',l||jsonb_build_object('rows',jsonb_build_array(f->'objects'->0)));
 perform public.payment_history_migration_worker_v1('fail',l||jsonb_build_object('code','history_worker_timeout'));
 return s;
end;$$;

select ok(not has_function_privilege('service_role','app_private.payment_history_local_baseline_recovery_v2(uuid,uuid,uuid,uuid,text,text,integer,jsonb)','EXECUTE'),'retry stays behind authenticated composition');
select ok((select relrowsecurity from pg_class where oid='app_private.payment_history_baseline_recovery_intents'::regclass),'failure audit remains private with RLS');
select throws_ok($$select pg_temp.baseline_request(1,'resume','{}')$$,'22023','payment_history_operation_invalid','raw baseline resume remains unavailable');
select lives_ok($$insert into state values('start',pg_temp.prepare_failed())$$,'actual original job fails through the Worker timeout path');
insert into state values('failed-original',pg_temp.run_snapshot());
select is(pg_temp.run_snapshot()->>'error_code','history_worker_timeout','failure reason is the eligible timeout');
select is(pg_temp.run_snapshot()->>'attempts','1','original Worker consumed one attempt');
select is(pg_temp.run_snapshot()->>'processed_objects','1','original timeout retains a nonempty staged prefix');
select throws_ok($$select pg_temp.recovery(1,pg_temp.retry_payload()-'retry_failed')$$,'40001','payment_history_baseline_recovery_conflict','ordinary session recovery cannot reopen failed work');
select throws_ok($$select pg_temp.recovery(1,pg_temp.retry_payload()||jsonb_build_object('retry_failed',false))$$,'22023','payment_history_baseline_recovery_invalid','false is not explicit retry intent');
